export const TODAY = '2026-10-28'; // Reproducible demonstration date, not a live clock.
export const statusLabels={pending:'Pending review',approved:'Approved',returned:'Returned',rejected:'Rejected'};
const names=['Meena Kumari','Senthil Kumar','Kalaiselvi','Mohammed Imran','Lakshmi Devi','Arun Prasad','Fathima Banu','Saravanan','Kavitha Rajan','Ramesh Kannan','Mary Joseph','Priya Selvam'];
const places=['Avaniyapuram','Thiruparankundram','Vilacheri','Thirunagar'];
export function seed(){return names.map((name,i)=>({id:`REV-103-${String(2418+i)}`,name,village:places[i%4],submitted:`2026-10-${String([8,12,14,15,17,18,19,20,21,22,23,25][i]).padStart(2,'0')}`,income:[96000,144000,72000,180000,84000,120000,108000,156000,60000,132000,192000,90000][i],evidenceIncome:i===1?168000:i===3?204000:[96000,144000,72000,180000,84000,120000,108000,156000,60000,132000,192000,90000][i],members:[3,4,2,5][i%4],occupation:i%2?'Private company employee':'Daily wage worker',purpose:i%3?'Education scholarship':'Tuition fee concession',status:'pending',docs:[{key:'photo',title:'Applicant photo',present:true},{key:'address',title:'Address proof',present:true},{key:'family',title:'Family card',present:i!==2},{key:'declaration',title:'Self-declaration',present:i!==4},{key:'income',title:i%2?'Salary certificate':'Income statement',present:i!==0&&i!==6}],history:[]}));}
export function age(a){return Math.floor((Date.parse(TODAY)-Date.parse(a.submitted))/86400000);}
export function assess(a){const missing=a.docs.filter(d=>!d.present);const inconsistent=a.evidenceIncome!==a.income&&a.docs.find(d=>d.key==='income').present;const issues=missing.map(d=>`${d.title} Not attached.`);if(inconsistent)issues.push(`Declared income ₹${a.income.toLocaleString('en-IN')}; Income evidence shows ₹${a.evidenceIncome.toLocaleString('en-IN')}. Clarification needed.`);return {missing,inconsistent,issues,suggestion:issues.length?'returned':'approved',reason:issues.length?issues.join(' '):'The sample checklist is complete and the declared income matches the evidence. The officer must verify the authenticity of original documents.'};}
export function priority(a){return age(a)>=15?'overdue':assess(a).issues.length?'attention':'normal';}
export function decide(a,status,reason,verified){if(a.status!=='pending')throw new Error('A decision has already been recorded for this application.');if(!['approved','returned','rejected'].includes(status))throw new Error('Invalid decision.');if(!verified||reason.trim().length<12)throw new Error('Verify the documents and enter a reason of at least 12 characters.');return {...a,status,history:[...a.history,{status,reason:reason.trim(),officer:'A. Tamilselvi',at:new Date().toISOString()}]};}
